{"path": "fizzbuzz.py", "content": "def fizzbuzz(n):
    """Return FizzBuzz strings for the numbers 1..n."""
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result


if __name__ == "__main__":
    import sys

    print("\n".join(fizzbuzz(int(sys.argv[1]) if len(sys.argv) > 1 else 100)))
"}

